<section class="section role-page"><div class="container role-container"><p class="eyebrow">Un primer paso</p><h1>¿Cómo vas a participar<br>en la red?</h1><p class="role-intro">Elegí el perfil que describe tu actividad. Así vamos a preparar un espacio a tu medida.</p><?php $roles = ['client' => ['Cliente', 'Buscá, compará y guardá propiedades. Coordiná visitas y seguí cada consulta desde un solo lugar.', 'Explorar oportunidades'], 'agency' => ['Inmobiliaria', 'Administrá propiedades, captaciones y consultas comerciales de tu cartera.', 'Gestionar mi inmobiliaria'], 'developer' => ['Desarrolladora', 'Organizá emprendimientos, unidades, reservas y avances de obra.', 'Gestionar proyectos']]; ?><div class="role-grid"><?php foreach ($roles as $value => [$label, $description, $action]): ?><form class="role-card" action="<?= e(url('/auth/choose-role')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="role" value="<?= e($value) ?>"><span class="role-icon"><?= e(strtoupper(substr($label, 0, 1))) ?></span><h2><?= e($label) ?></h2><p><?= e($description) ?></p><button class="text-link" type="submit"><?= e($action) ?> <span aria-hidden="true">→</span></button></form><?php endforeach; ?></div></div></section>
